--region import
---@type DreamAdventuresMgr
local DreamAdventuresMgr = import("Game.Activity.DreamAdventures.DreamAdventuresMgr"):GetInstance()
--endregion import

--region define
local CoWait = CS.Engine.Lib.CoWait
local UIModule = CS.Engine.UI.UIModule
--endregion define

local TYPE = {
    TASK = 1,
    ACH = 2, ---成就
}

--- from: Assets/BundleResources/Prefabs/ActivityDreamAdventures12000801/ActivityDreamAdventureslDreamAdventuresTaskDialog.prefab > name: ActivityDreamAdventureslDreamAdventuresTaskDialog
---@class DreamAdventuresTaskDialog
---@field Env                           	DreamAdventuresTaskDialog               
---@field controller                    	Engine.UI.UILuaDialog                   
---@field ListView                      	SuperScrollView.LoopListView2           
---@field RightPanel                    	UnityEngine.RectTransform               
---@field ImgBg                         	UnityEngine.RectTransform               
---@field Container                     	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
---@field FontStyleButton               	UnityEngine.RectTransform               
local DreamAdventuresTaskDialog = Class("DreamAdventuresTaskDialog")

--region lifecycle
function DreamAdventuresTaskDialog:__init()
    self._taskData = {}
    self._taskList = {}
    self._events   = {}
    self.type = TYPE.TASK
end
function DreamAdventuresTaskDialog:__delete()
    self._taskData = nil
    self._taskList = nil
    self._events   = nil
end

function DreamAdventuresTaskDialog:Awake()
    local  parameters = self.controller.Argument.parameters
    if parameters.type then
        self.type = checkNumber(parameters.type)
    end
end

function DreamAdventuresTaskDialog:OnInitialize()
    self:InitHandler()
    self:InitData()
end

function DreamAdventuresTaskDialog:OnFinalize()
    for k, v in pairs(self._events) do
        Events.RemoveListener(k, v)
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function DreamAdventuresTaskDialog:InitHandler()
    self._events[Constants.EventNames.DreamAdventuresTaskDraw] = Events.AddListener(Constants.EventNames.DreamAdventuresTaskDraw, Bind(self, self.TaskDrawEventHandler))
    if self.type == TYPE.ACH then
        CfUtils.SetActive(self.BtnRoleNameNode, false)
        CfUtils.FillImage(self.ImgBg, "Arts/Textures/Activity/DreamAdventures12000801/activity_catfood_task_bg.png")
    end
    SetButtonAction(self.FontStyleButton, Bind(self, self.BtnDrawAllOnClickHandler))
    if self.type == TYPE.ACH then
        CfUtils.SetActive(self.Text2.transform.parent, false)
        CfUtils.SetActive(self.BtnRoleNameNode.transform.parent, false)
    end
end

function DreamAdventuresTaskDialog:InitData()
    local activityId = DreamAdventuresMgr:GetActivityId()
    GameUtils.Request(Interfaces.DreamAdventuresTask, {activityUuid = activityId, type = self.type}, Bind(self, self.TaskHomeResponseHandler))
end
--endregion init

--region handler
---列表刷新
function DreamAdventuresTaskDialog:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self:GetTaskList()[luaIndex]
    local cell = listView:NewListViewItem("CellNode")
    ---@type DreamAdventuresTaskCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.DreamAdventures.DreamAdventuresTaskCell")
    scr:Refresh(cellData, self.type)
    if luaIndex <= listView.DisplayItemCount then
        CfUtils.PlayDelayShowAnimation(cell, index)
    end
    return cell
end

---一键领取按钮回调
function DreamAdventuresTaskDialog:BtnDrawAllOnClickHandler()
    self:DrawRequest()
end

---领取任务奖励事件处理
function DreamAdventuresTaskDialog:TaskDrawEventHandler(taskId)
    self:DrawRequest(taskId)
end

---任务home回调处理
function DreamAdventuresTaskDialog:TaskHomeResponseHandler(request, response)
    table.sort(response.data.task, function(a, b)
        local aStatus = checkInt(a.status)
        local bStatus = checkInt(b.status)
        if aStatus == bStatus then
            return checkInt(a.id) < checkInt(b.id)
        else
            if aStatus == 1 then
                return true
            elseif bStatus == 1 then 
                return false
            elseif aStatus == 2 then
                return false
            elseif bStatus == 2 then
                return true
            else
                return false
            end
        end
    end)
    self:SetTaskData(response.data)
    self:SetTaskList(self:GetTaskData().task)
    
    -- 更新红点
    local tips = -1
    for i, v in ipairs(self:GetTaskList()) do
        if checkInt(v.status) == 1 then
            tips = 0
            break
        end
    end
    DreamAdventuresMgr:SetTaskTips(tips, self.type)
    self:RefreshUI()
end

---任务领取回调处理
function DreamAdventuresTaskDialog:TaskDrawResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    
    local jsonData = response.data
    local rewards = checkTable(jsonData.rewards)
    if #rewards > 0 then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end
    
    self:InitData()
end
--endregion handler

--region private
---刷新UI
function DreamAdventuresTaskDialog:RefreshUI()
    local taskCount = table.count(self:GetTaskList())
    if self.type == TYPE.ACH then
        CfUtils.SetActive(self.BtnRoleNameNode.transform.parent, taskCount > 0)
        --CfUtils.SetActive(self.Text2.transform.parent, taskCount > 0)
        if taskCount > 0 then
            local vo = DreamAdventuresMgr:GetScheduleVo()
            if checkNumber(vo.storeCornId) > 0 then
                local goodsId = checkNumber(vo.storeCornId)
                local haveNo = GoodsUtils.GetThingNo(goodsId)
                local photoPath = GoodsUtils.GetGoodsIconById(goodsId)
                CfUtils.FillImage(self.ImgIcon, photoPath)
                CfUtils.FillText(self.ImgIcon.transform.parent:Find("TexNumber"), haveNo)
            end
        end
    end
    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(taskCount, Bind(self, self.OnGetItemByIndex))
        self.ListView:UpdateDisplayItemCount("CellNode")
    else
        GameUtils.ReloadData(self.ListView, taskCount)
    end
end

---领取请求
---@param taskId number 任务id,为空为一键领取
function DreamAdventuresTaskDialog:DrawRequest(taskId)
    local taskList = self:GetTaskList()
    local canDraw = false
    for _, v in ipairs(taskList) do
        if v.status == 1 then
            canDraw = true
            break
        end
    end
    if not canDraw then
        GameUtils.Toast(localize('暂无可领取的奖励'))
        return
    end

    local activityId = DreamAdventuresMgr:GetActivityId()
    GameUtils.Request(Interfaces.DreamAdventuresDrawTask, {activityUuid = activityId, id = taskId, type = self.type}, Bind(self, self.TaskDrawResponseHandler))
end
--endregion private

--region get / set
---设置任务数据
function DreamAdventuresTaskDialog:SetTaskData(taskData)
    self._taskData = checkTable(taskData)
end

---获取任务数据
function DreamAdventuresTaskDialog:GetTaskData()
    return self._taskData
end

---设置任务列表数据
function DreamAdventuresTaskDialog:SetTaskList(taskList)
    self._taskList = checkTable(taskList)
end

---获取任务列表数据
function DreamAdventuresTaskDialog:GetTaskList()
    return self._taskList
end
--endregion get / set

return DreamAdventuresTaskDialog